def grade(case, answer, judge):
    # closed check first: fast and free
    if case.get("must_include"):
        if case["must_include"].lower() not in answer.lower():
            return 0.0
    # nuanced check: ask a judge against the written expectation
    verdict = judge(
        question=case["input"],
        answer=answer,
        rubric=case["expect"],
    )
    return verdict.score  # 0.0 to 1.0

