import os
import psycopg2
from fastapi import FastAPI, HTTPException

app = FastAPI()

def _decide(approval_id: int, status: str) -> dict:
    conn = psycopg2.connect(os.environ["DATABASE_URL"])
    with conn, conn.cursor() as cur:
        cur.execute(
            "UPDATE approvals SET status = %s, decided_at = now() "
            "WHERE id = %s AND status = 'pending' RETURNING action, payload",
            (status, approval_id),
        )
        row = cur.fetchone()
    conn.close()
    if row is None:
        raise HTTPException(404, "not pending or not found")
    return {"action": row[0], "payload": row[1]}

@app.post("/approvals/{approval_id}/approve")
def approve(approval_id: int):
    job = _decide(approval_id, "approved")
    # run the real action now, from the stored payload:
    # send_refund(**job["payload"])
    return {"ok": True, "ran": job["action"]}

@app.post("/approvals/{approval_id}/reject")
def reject(approval_id: int):
    _decide(approval_id, "rejected")
    return {"ok": True}

