def judge(reply, rubric):
    r = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{
            "role": "user",
            "content": (
                f"Reply:\n{reply}\n\n"
                f"Does it satisfy this rule? {rubric}\n"
                "Answer only YES or NO."
            ),
        }],
    )
    return r.choices[0].message.content.strip().upper().startswith("YES")

