import json
from openai import OpenAI

client = OpenAI()

PROMPT = """You are a grounding checker. Decide if the ANSWER is fully supported by the SOURCES.
An answer is grounded only if every factual claim in it appears in or follows directly from the sources.
Contradictions or invented specifics (numbers, dates, policies) are NOT grounded.

QUESTION: {question}
SOURCES: {sources}
ANSWER: {answer}

Reply as JSON: {{"grounded": true|false, "unsupported_claim": "<the worst unsupported claim, or empty>"}}"""

def check(record):
    msg = PROMPT.format(
        question=record["question"],
        sources="\n".join(record["sources"]),
        answer=record["answer"],
    )
    resp = client.chat.completions.create(
        model="gpt-4o-mini",
        messages=[{"role": "user", "content": msg}],
        response_format={"type": "json_object"},
        temperature=0,
    )
    return json.loads(resp.choices[0].message.content)

